query($item:ID!){
  node(id:$item){
    ... on ProjectV2Item {
      id
      fieldValues(first:50){
        nodes{
          ... on ProjectV2ItemFieldTextValue{ text field{ ... on ProjectV2FieldCommon{ name } } }
          ... on ProjectV2ItemFieldSingleSelectValue{ optionId field{ ... on ProjectV2FieldCommon{ name } } }
        }
      }
    }
  }
}
